  LinearLayout hw=card(side,compact?"Yamaha · salvo":"Seu Yamaha",null),title=row();
  title.addView(new InstrumentArt(this,2),new LinearLayout.LayoutParams(dp(compact?44:78),dp(compact?40:62)));
  LinearLayout labels=column();headline=text("Som original",compact?13:17,FG);labels.addView(headline);if(!compact)labels.addView(text("P-145BT / controle MIDI",11,MUTED));title.addView(labels,new LinearLayout.LayoutParams(0,-2,1));hw.addView(title);
