  if(compact){buttons(hw,button("Alterar",()->compact("yamahaCompact",false)));return;}
  hw.addView(text("A configuração é salva e reaplicada ao reconectar.",11,MUTED));
  buttons(hw,button("Só app",()->chooseYamaha(true)),button("Misturar",()->chooseYamaha(false)));
