 private void renameLibraryDialog(Set<String> files,boolean returnToManager){
  final PianoService service=session;if(service==null||!service.ready||service.loading){toast("Aguarde o carregamento atual.");return;}
  Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);LinearLayout root=column();root.setPadding(dp(16),dp(12),dp(16),dp(12));root.setBackgroundColor(BG);
  root.addView(text(files.size()==1?"Renomear biblioteca":"Renomear bibliotecas",20,TEAL));root.addView(text("Escolha nomes que sejam fáceis de reconhecer. Favoritos, timbres, cenas e configurações conservam suas referências.",12,MUTED));
  LinearLayout fields=column();LinkedHashMap<String,EditText> inputs=new LinkedHashMap<>();
  for(PianoService.Bank bank:service.orderedBanks())if(files.contains(bank.file.getName())){
   fields.addView(text(bank.name,15,TEAL));fields.addView(text("Nome original: "+bank.originalName,12,MUTED));EditText input=new EditText(this);input.setText(bank.name);input.setSingleLine(true);input.setMinHeight(dp(52));input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(100)});input.setSelectAllOnFocus(true);input.setContentDescription("Nome da biblioteca "+bank.originalName);fields.addView(input,new LinearLayout.LayoutParams(-1,-2));
   fields.addView(button("Usar nome original",()->input.setText(bank.originalName)));inputs.put(bank.file.getName(),input);
  }
  root.addView(scrolling(fields),new LinearLayout.LayoutParams(-1,0,1));
  buttons(root,button(files.size()==1?"Salvar nome":"Salvar todos",()->{LinkedHashMap<String,String> changes=new LinkedHashMap<>();try{for(Map.Entry<String,EditText> entry:inputs.entrySet())changes.put(entry.getKey(),LibraryEdits.name(entry.getValue().getText().toString()));}catch(IOException error){toast(error.getMessage());return;}if(service.renameLibraries(changes,null)){dialog.dismiss();buildUi();if(returnToManager)libraryManager();toast(service.message);}else toast(service.message);}),button("Cancelar",()->{dialog.dismiss();if(returnToManager)libraryManager();}));
  safeInsets(root);dialog.setContentView(root);dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getWindow().setLayout(-1,-1);
 }
