  safeInsets(root);dialog.setContentView(root);dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getWindow().setLayout(-1,-1);
  service.generalCatalog((result,problem)->{if(!dialog.isShowing()||isFinishing()||isDestroyed())return;entries.clear();entries.addAll(result);warning[0]=problem;indexed[0]=true;catalogLoading.setVisibility(View.GONE);grid.setVisibility(View.VISIBLE);filter[0].run();});
