 private void drawRecordings(){
  if(recordingsList==null)return;recordingsList.removeAllViews();shownRecordings=session.recordingRevision;
  File[] list=session.recordings();if(list.length==0)recordingsList.addView(text("Sua primeira gravação aparecerá aqui.",14,MUTED));
  for(File file:list){boolean video=file.getName().endsWith(".mp4"),midi=file.getName().endsWith(".mid");
   LinearLayout tile=column();tile.setPadding(dp(8),dp(8),dp(8),dp(10));tile.setBackground(rounded(RoomTheme.SOFT,14));
   LinearLayout details=row();FrameLayout picture=new FrameLayout(this);picture.setBackground(rounded(RoomTheme.SOFT,10));picture.addView(new InstrumentArt(this,video?2:1),new FrameLayout.LayoutParams(-1,-1));
   if(video){ImageView preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setContentDescription("Miniatura do vídeo "+file.getName());picture.addView(preview,new FrameLayout.LayoutParams(-1,-1));RecordingPreview.bind(preview,file);}
   details.addView(picture,new LinearLayout.LayoutParams(dp(110),dp(74)));LinearLayout label=column();label.setPadding(dp(10),0,0,0);
   label.addView(text((midi?"♫ MIDI":video?"▣ Vídeo":"≋ Áudio WAV")+" • "+String.format(Locale.US,"%.1f MB",file.length()/1048576.0),14,FG));
   label.addView(text(new java.text.SimpleDateFormat("dd/MM/yyyy • HH:mm",Locale.getDefault()).format(new Date(file.lastModified())),12,MUTED));
   TextView name=text(file.getName(),10,MUTED);name.setMaxLines(2);label.addView(name);details.addView(label,new LinearLayout.LayoutParams(0,-2,1));tile.addView(details);
   buttons(tile,button("Reproduzir",()->playRecording(file)),button(video?"Galeria":"Exportar",()->{if(video&&Build.VERSION.SDK_INT>=29)session.saveGallery(file,()->toast(session.captureStatus));else exportRecording(file);}));
   Button delete=button("Excluir",()->deleteRecording(file));delete.setBackgroundTintList(ColorStateList.valueOf(RoomTheme.RED));delete.setContentDescription("Excluir "+file.getName());
   if(video)buttons(tile,button("Exportar arquivo",()->exportRecording(file)),delete);else if(midi)buttons(tile,button("Editar notas",()->session.editMidi(file,model->midiEditor(model))),delete);else buttons(tile,delete);
   LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-1,-2);margin.setMargins(0,0,0,dp(10));recordingsList.addView(tile,margin);
  }
 }
 private void midiEditor(MidiEdit model){Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);LinearLayout root=column();root.setBackgroundColor(BG);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.addView(text("Editor MIDI · toque em uma nota",19,TEAL));root.addView(text("Ajusta altura, intensidade e duração. Salva uma cópia; pedal e demais controles são preservados.",12,MUTED));LinearLayout controls=column();PianoRoll roll=new PianoRoll(model,controls);HorizontalScrollView time=new HorizontalScrollView(this);time.addView(roll,new ViewGroup.LayoutParams(Math.min(dp(12000),Math.max(dp(500),(int)(model.duration/1000000.0*dp(100)))),dp(getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE?130:210)));root.addView(time);root.addView(scrolling(controls),new LinearLayout.LayoutParams(-1,0,1));buttons(root,button("Desfazer tudo",()->{dialog.dismiss();midiEditor(new MidiEdit(modelOriginal(model)));}),button("Salvar cópia",()->{session.saveMidiEdit(model);dialog.dismiss();}),button("Fechar",dialog::dismiss));safeInsets(root);dialog.setContentView(root);dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getWindow().setLayout(-1,-1);}
 private java.util.List<MidiTape.Event> modelOriginal(MidiEdit model){return model.original();}
 private final class PianoRoll extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final MidiEdit model;private final LinearLayout controls;private MidiEdit.Note selected;private int low=127,high;PianoRoll(MidiEdit m,LinearLayout c){super(MainActivity.this);model=m;controls=c;for(MidiEdit.Note n:m.notes){low=Math.min(low,n.key);high=Math.max(high,n.key);}low=Math.max(0,low-3);high=Math.min(127,Math.max(low+12,high+3));setContentDescription("Piano roll de notas MIDI · toque para editar");}protected void onDraw(Canvas canvas){p.setStrokeWidth(dp(1));float h=getHeight()/(float)(high-low+1);for(int k=low;k<=high;k++){p.setColor(k%12==1||k%12==3||k%12==6||k%12==8||k%12==10?0xFFE1E1D9:RoomTheme.SOFT);canvas.drawRect(0,(high-k)*h,getWidth(),(high-k+1)*h,p);}p.setColor(RoomTheme.BORDER);for(long t=0;t<=model.duration;t+=1000000){float x=t*getWidth()/(float)model.duration;canvas.drawLine(x,0,x,getHeight(),p);}for(MidiEdit.Note n:model.notes)if(!n.deleted){p.setColor(n==selected?GOLD:TEAL);float x=n.start*getWidth()/(float)model.duration,right=n.end*getWidth()/(float)model.duration,y=(high-n.key)*h;canvas.drawRoundRect(x,y+1,Math.max(x+dp(5),right),y+h-1,dp(2),dp(2),p);}}public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;float h=getHeight()/(float)(high-low+1);MidiEdit.Note best=null;float distance=dp(24);for(MidiEdit.Note n:model.notes)if(!n.deleted){float x=n.start*getWidth()/(float)model.duration,r=n.end*getWidth()/(float)model.duration,y=(high-n.key+.5f)*h;float dx=e.getX()<x?x-e.getX():e.getX()>r?e.getX()-r:0;float d=(float)Math.hypot(dx,e.getY()-y);if(d<distance){distance=d;best=n;}}if(best!=null){selected=best;edit();invalidate();performClick();}return true;}private void edit(){controls.removeAllViews();MidiEdit.Note n=selected;controls.addView(text("Nota "+n.key+" · canal "+(n.channel+1),15,FG));slider(controls,"Altura MIDI",0,127,n.key,v->{n.key=v;low=Math.min(low,v);high=Math.max(high,v);invalidate();});slider(controls,"Intensidade",1,127,n.velocity,v->{n.velocity=v;invalidate();});int maxMs=(int)Math.min(Integer.MAX_VALUE,model.duration/1000);slider(controls,"Início (ms)",0,Math.max(0,maxMs-1),(int)(n.start/1000),v->{long length=n.end-n.start;n.start=v*1000L;n.end=Math.min(model.duration,n.start+length);invalidate();});slider(controls,"Duração (ms)",1,Math.max(1,maxMs),(int)((n.end-n.start)/1000),v->{n.end=Math.min(model.duration,n.start+v*1000L);invalidate();});buttons(controls,button("Excluir nota",()->{n.deleted=true;controls.removeAllViews();invalidate();}));}public boolean performClick(){super.performClick();return true;}}
 private void playRecording(File file){if(session.fileBusy(file)){toast("Aguarde a gravação terminar.");return;}if(file.getName().endsWith(".mid"))new AlertDialog.Builder(this).setTitle("Reproduzir MIDI").setItems(new String[]{"Usar timbres atuais","Restaurar cena da gravação"},(d,n)->session.playMidi(file,n==1)).show();else if(file.getName().endsWith(".wav"))session.playWave(file);else{session.stopPlayback();startActivity(new Intent(this,VideoPlaybackActivity.class).putExtra("path",file.getAbsolutePath()));}}
 private void deleteRecording(File file){if(!session.deletingAllowed(file)){toast("Finalize a gravação ou pare a reprodução antes de excluir.");return;}new AlertDialog.Builder(this).setTitle("Excluir esta gravação?").setMessage(file.getName()+"\n\nExclui a cópia do aplicativo. Uma cópia já salva na galeria será mantida.").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(d,w)->session.deleteRecording(file,()->{drawRecordings();toast(session.captureStatus);})).show();}
 private void exportRecording(File file){if(session.fileBusy(file)){toast("Finalize a gravação antes de exportar.");return;}exportFile=file;String type=file.getName().endsWith(".mid")?"audio/midi":file.getName().endsWith(".wav")?"audio/wav":"video/mp4";startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(type).putExtra(Intent.EXTRA_TITLE,file.getName()),45);}
