 private final class XYPad extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);XYPad(){super(MainActivity.this);setBackground(rounded(RoomTheme.SOFT,16));setContentDescription("Controle XY · mistura de timbres e macro de efeito");setFocusable(true);}protected void onDraw(Canvas c){float pad=dp(20),w=getWidth()-2*pad,h=getHeight()-2*pad;p.setColor(RoomTheme.BORDER);p.setStrokeWidth(dp(1));for(int i=0;i<5;i++){c.drawLine(pad,pad+i*h/4,pad+w,pad+i*h/4,p);c.drawLine(pad+i*w/4,pad,pad+i*w/4,pad+h,p);}p.setColor(session.xyEnabled?TEAL:MUTED);float x=pad+w*session.xyX,y=pad+h*(1-session.xyY);c.drawLine(x,pad,x,pad+h,p);c.drawLine(pad,y,pad+w,y,p);c.drawCircle(x,y,dp(9),p);p.setTextSize(dp(12));c.drawText("C"+(session.xyA+1)+" ← mistura → C"+(session.xyB+1),pad,getHeight()-dp(4),p);}public boolean onTouchEvent(MotionEvent e){if(!session.xyEnabled)return false;int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN||a==MotionEvent.ACTION_MOVE){getParent().requestDisallowInterceptTouchEvent(true);session.xy((e.getX()-dp(20))/Math.max(1,getWidth()-dp(48)),1-(e.getY()-dp(20))/Math.max(1,getHeight()-dp(48)));invalidate();return true;}if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);session.savePreset(false);performClick();return true;}return true;}public boolean performClick(){super.performClick();return true;}}
